private void AssertInterval(IList<long> fires, long milliseconds)
{
            var delta = 10L; // milliseconds
            var prevtick = fires[0];
            for (int i = 1; i < fires.Count; i++)
            {
                var diffMillis = (fires[i] - prevtick) / TimeSpan.TicksPerMillisecond;
                var actualDelta = diffMillis - milliseconds;
                if (actualDelta > delta || actualDelta < -delta)
                {
                    Assert.Warn($"Expected an interval of {milliseconds} but got {diffMillis}.");
                }

                prevtick = fires[i];
            }
        }

internal void UpdateWorkerMainState()
{
            switch (State)
            {
                case WorkerState.Idle:
                    break;
                case WorkerState.Running:
                    ThreadCallbackUpdate();
                    break;
                case WorkerState.WaitingClose:
                    ThreadCallbackClosed();
                    HyperThreadDispatcher.DetachWorker(this);
                    break;
                case WorkerState.CloseError:
                    ThreadCallbackError();
                    HyperThreadDispatcher.DetachWorker(this);
                    break;
                default:
                    throw new ArgumentOutOfRangeException();
            }
        }

internal void ThreadRunnerWrapper()
{
            try
            {
                State = WorkerState.Running;
                StateProgress = 0f;
                ThreadBody();
                StateProgress = 1f;
                State = WorkerState.WaitingClose;
            }
            catch (Exception e)
            {
                Debug.LogError($"Thread {Thread.CurrentThread.Name} closed prematurely, ERROR: {e.Message}");
                State = WorkerState.CloseError;
            }
        }

private void SetSecret(string id, string key, string value)
{
            var secretsFilePath = PathHelper.GetSecretsPathFromSecretsId(id);

            var dir = Path.GetDirectoryName(secretsFilePath);
            Directory.CreateDirectory(dir);
            _tmpDirectories.Add(dir);

            var secrets = new ConfigurationBuilder()
                .AddJsonFile(secretsFilePath, optional: true)
                .Build()
                .AsEnumerable()
                .Where(i => i.Value != null)
                .ToDictionary(i => i.Key, i => i.Value, StringComparer.OrdinalIgnoreCase);

            secrets[key] = value;

            var contents = new JObject();
            if (secrets != null)
            {
                foreach (var secret in secrets.AsEnumerable())
                {
                    contents[secret.Key] = secret.Value;
                }
            }

            File.WriteAllText(secretsFilePath, contents.ToString(), Encoding.UTF8);
        }

