private void OnBuildingDelivered(BuildingTaskData taskData)
{
            _data.tasks.Remove(taskData);
            _data.buildings.Add(taskData.building);

            UpdateTasks();
            UpdateBuildings();

            _signalBus.Fire(new MetaGameDataChangedSignal());
        }

