public static void LoadThemes ()
{
		string [] files = Directory.GetFiles (CLI.currentPath, "*Themes.dll");
		if (files.Length > 0)
			AddThemesToDB (files);
		string path = Path.Combine (CLI.currentPath, "Themes");
		if (Directory.Exists (path))
		{
