			int dUsec = mUSec;
			var sb = new StringBuilder(); 
			if ( dSec < 0 )
			{
				dSec++;
				if ( dSec == 0)
					sb.Append('-');
				dUsec = 1000000 - dUsec;
			}
			sb.AppendFormat("{0}.{1,6:D6}", dSec, dUsec);
			return sb.ToString();
		}

