private static bool TraverseTransform(this Transform obj, Func<Transform, bool> doFunc)
{
			if (!doFunc(obj))
			{
				return false;
			}
			for (int i = 0; i < obj.childCount; i++)
			{
				Transform child = obj.GetChild(i);
				if (!child.TraverseTransform(doFunc))
				{
					return false;
				}
			}
			return true;
		}

