{
            string result = string.Empty;

            if (value == null)
                return result;

            try
            {
                TimeSpan ts = (TimeSpan)value;

                if (ts.Days > 0) result = result + String.Format("{0}d ",ts.Days);
                result = result + String.Format("{0}h ", ts.Hours);
                result = result + String.Format("{0}m", ts.Minutes);
            }
            catch { }

            return result;
        }

