                if (!System.Text.RegularExpressions.Regex.IsMatch(Country, "^[A-Z]{2,2}$"))
                {
                    throw new ValidationException(ValidationRules.Pattern, "Country", "^[A-Z]{2,2}$");
                }
            }
        }

