protected override void Definition()
{
            if (numeric)
            {
                a = ValueInput<float>(nameof(a));
                b = ValueInput<float>(nameof(b), 0);
                comparison = ValueOutput(outputKey, NumericComparison).Predictable();
            }
            else
            {
                a = ValueInput<object>(nameof(a)).AllowsNull();
                b = ValueInput<object>(nameof(b)).AllowsNull();
                comparison = ValueOutput(outputKey, GenericComparison).Predictable();
            }

            Requirement(a, comparison);
            Requirement(b, comparison);
        }

private bool NumericComparison(Flow flow)
{
            return NumericComparison(flow.GetValue<float>(a), flow.GetValue<float>(b));
        }

private LoggingLevelSwitch SetLogLevel(string logLevelKey)
{
            var appLogginglevelSwitch = new LoggingLevelSwitch();
            switch (logLevelKey)
            {
                case "Verbose":
                    appLogginglevelSwitch.MinimumLevel = LogEventLevel.Verbose;
                    break;
                case "Debug":
                    appLogginglevelSwitch.MinimumLevel = LogEventLevel.Debug;
                    break;
                case "Information":
                    appLogginglevelSwitch.MinimumLevel = LogEventLevel.Information;
                    break;
                case "Warning":
                    appLogginglevelSwitch.MinimumLevel = LogEventLevel.Warning;
                    break;
                case "Error":
                    appLogginglevelSwitch.MinimumLevel = LogEventLevel.Error;
                    break;
                case "Fatal":
                    appLogginglevelSwitch.MinimumLevel = LogEventLevel.Fatal;
                    break;
                default:
                    appLogginglevelSwitch.MinimumLevel = LogEventLevel.Information;
                    break;
            }
            return appLogginglevelSwitch;
        }

