public static void Render(this DrawingContext context, IVisual visual)
{
            context.Render(visual, visual.Bounds);
        }

private static void Render(this DrawingContext context, IVisual visual, Rect clipRect)
{
            var opacity = visual.Opacity;
            var clipToBounds = visual.ClipToBounds;
            var bounds = new Rect(visual.Bounds.Size);

            if (visual.IsVisible && opacity > 0)
            {
                var m = Matrix.CreateTranslation(visual.Bounds.Position);

                var renderTransform = Matrix.Identity;

                if (visual.RenderTransform != null)
                {
                    var origin = visual.RenderTransformOrigin.ToPixels(new Size(visual.Bounds.Width, visual.Bounds.Height));
                    var offset = Matrix.CreateTranslation(origin);
                    renderTransform = (-offset) * visual.RenderTransform.Value * (offset);
                }

                m = renderTransform * m;

                if (clipToBounds)
                {
                    clipRect = clipRect.Intersect(new Rect(visual.Bounds.Size));
                }

                using (context.PushPostTransform(m))
                using (context.PushOpacity(opacity))
                using (clipToBounds ? context.PushClip(bounds) : default(DrawingContext.PushedState))
                using (visual.Clip != null ? context.PushGeometryClip(visual.Clip) : default(DrawingContext.PushedState))
                using (visual.OpacityMask != null ? context.PushOpacityMask(visual.OpacityMask, bounds) : default(DrawingContext.PushedState))
                using (context.PushTransformContainer())
                {
                    visual.Render(context);
                    var transformed =
                        new TransformedBounds(bounds, new Rect(), context.CurrentContainerTransform);
                    if (visual is Visual)
                    {
                        BoundsTracker.SetTransformedBounds((Visual)visual, transformed);
                    }

                    var lst = GetSortedVisualList(visual.VisualChildren);

                    foreach (var child in lst)
                    {
                        var childBounds = GetTransformedBounds(child);

                        if (!child.ClipToBounds || clipRect.Intersects(childBounds))
                        {
                            var childClipRect = clipRect.Translate(-childBounds.Position);
                            context.Render(child, childClipRect);
                        }
                        else
                        {
                            ClearTransformedBounds(child);
                        }
                    }

                    ReturnListToPool(lst);
                }
            }

            if (!visual.IsVisible)
            {
                ClearTransformedBounds(visual);
            }
        }

private static void ClearTransformedBounds(IVisual visual)
{
            foreach (var e in visual.GetSelfAndVisualDescendents())
            {
                BoundsTracker.SetTransformedBounds((Visual)visual, null);
            }
        }

private static void ReturnListToPool(List<IVisual> lst)
{
            lst.Clear();
            s_listPool.Push(lst);
        }

private static List<IVisual> GetSortedVisualList(IReadOnlyList<IVisual> source)
{
            var lst = s_listPool.Count == 0 ? new List<IVisual>() : s_listPool.Pop();
            for (var c = 0; c < source.Count; c++)
                lst.Add(source[c]);
            lst.Sort(s_visualComparer);
            return lst;
        }

private static Rect GetTransformedBounds(IVisual visual)
{
            if (visual.RenderTransform == null)
            {
                return visual.Bounds;
            }
            else
            {
                var origin = visual.RenderTransformOrigin.ToPixels(new Size(visual.Bounds.Width, visual.Bounds.Height));
                var offset = Matrix.CreateTranslation(visual.Bounds.Position + origin);
                var m = (-offset) * visual.RenderTransform.Value * (offset);
                return visual.Bounds.TransformToAABB(m);
            }
        }

public async Task CanInstallAndUpdate()
{
            const string appName = "IncrementalDeploymentTests";
            const string packageId = "IncrementalDeployment";
            const string packageOldVersion = "1.0.0";
            const string packageLatestVersion = "2.0.0";
            const string externalFeed = "https://www.myget.org/F/simplesvc/";

            await ApplicationManager.RunAsync(appName, async appManager =>
            {
                var manager = appManager.SiteExtensionManager;
                await SiteExtensionApiFacts.CleanSiteExtensions(manager);

                TestTracer.Trace("Perform InstallExtension with id '{0}', version '{1}' from '{2}'", packageId, packageOldVersion, externalFeed);
                HttpResponseMessage responseMessage = await manager.InstallExtension(packageId, packageOldVersion, externalFeed, SiteExtensionInfo.SiteExtensionType.WebRoot);
                Assert.Equal(HttpStatusCode.OK, responseMessage.StatusCode);

                HttpClient client = new HttpClient();
                TestTracer.Trace("Package is installed to wwwroot, perform get to verify content.");
                responseMessage = await client.GetAsync(appManager.SiteUrl + "default.aspx");
                string responseContent = await responseMessage.Content.ReadAsStringAsync();
                Assert.True(responseContent.Contains("<h1>World's most amazing file counter</h1>"),
                    string.Format(CultureInfo.InvariantCulture, "Not contain expected content. Actual: {0}", responseContent));

                responseMessage = await client.GetAsync(appManager.SiteUrl + "delete.txt");
                responseContent = await responseMessage.Content.ReadAsStringAsync();
                Assert.Equal("delete", responseContent);

                responseMessage = await client.GetAsync(appManager.SiteUrl + "new.txt");
                Assert.Equal(HttpStatusCode.NotFound, responseMessage.StatusCode);

                responseMessage = await manager.InstallExtension(packageId, packageLatestVersion, externalFeed, SiteExtensionInfo.SiteExtensionType.WebRoot);
                Assert.Equal(HttpStatusCode.OK, responseMessage.StatusCode);
                responseMessage = await client.GetAsync(appManager.SiteUrl + "default.aspx");
                responseContent = await responseMessage.Content.ReadAsStringAsync();
                Assert.True(responseContent.Contains("<h1>World's most amazing file counter v2!</h1>"),
                    string.Format(CultureInfo.InvariantCulture, "Not contain expected content. Actual: {0}", responseContent));

                responseMessage = await client.GetAsync(appManager.SiteUrl + "new.txt");
                responseContent = await responseMessage.Content.ReadAsStringAsync();
                Assert.Equal("new", responseContent);

                responseMessage = await client.GetAsync(appManager.SiteUrl + "delete.txt");
                Assert.Equal(HttpStatusCode.NotFound, responseMessage.StatusCode);
            });
        }

