public void Paint(float x, float y)
{
            if (!Enabled) return;
            if (Brush == null) return;

            var radius = RadiusTransformator != null ? RadiusTransformator.TransformRadius(Radius) : Radius;

            if (HasShadow)
            {
                if (Brush.StrokeStyle.DashStyle == SharpDX.Direct2D1.DashStyle.Solid)
                {
                    ShadowBrush.StrokeWidth = Brush.StrokeWidth >= 0 ? Brush.StrokeWidth + 1 : Brush.StrokeWidth - 1;
                    ShadowBrush.DrawEllipse(x, y, radius, radius, -1);
                }
            }

            Brush.DrawEllipse(x, y, radius, radius, -1);
        }

public bool IsEnabled(LogEventLevel level, string area)
{
            return level >= _level && (_areas?.Contains(area) ?? true);
        }

public void Log(LogEventLevel level, string area, object source, string messageTemplate)
{
            if (IsEnabled(level, area))
            {
                Log(level, Format<object, object, object>(area, messageTemplate, source));
            }
        }

private void Log(LogEventLevel level, string message)
{
            switch (level)
            {
                case LogEventLevel.Warning:
                    Debug.LogWarning(message);
                    break;
                case LogEventLevel.Error:
                case LogEventLevel.Fatal:
                    Debug.LogError(message);
                    break;
                default:
                    Debug.Log(message);
                    break;
            }
        }

private static string Format(
            string area,
            string template,
            object source,
            object[] v)
{
            var result = new StringBuilder(template.Length);
            var r = new CharacterReader(template.AsSpan());
            var i = 0;

            result.Append('[');
            result.Append(area);
            result.Append(']');

            while (!r.End)
            {
                var c = r.Take();

                if (c != '{')
                {
                    result.Append(c);
                }
                else
                {
                    if (r.Peek != '{')
                    {
                        result.Append('\'');
                        result.Append(i < v.Length ? v[i++] : null);
                        result.Append('\'');
                        r.TakeUntil('}');
                        r.Take();
                    }
                    else
                    {
                        result.Append('{');
                        r.Take();
                    }
                }
            }

            if (source is object)
            {
                result.Append('(');
                result.Append(source.GetType().Name);
                result.Append(" #");
                result.Append(source.GetHashCode());
                result.Append(')');
            }

            return result.ToString();
        }

