public void WriteFunction()
{
            var res = TeeSquareFluent.StandardWriter()
                .Add(w =>
                {
                    w.WriteFunction("HelloWorld", "T1 extends number")
                        .WithReturnType(new TypeReference("number"))
                        .WithBody(body =>
