public async Task<IActionResult> Get(int currentPageNo = 1, int pageSize = 20)
{
      var users = await _context.User
          .OrderByDescending(u => u.EntryTime)
          .Skip((currentPageNo - 1) * pageSize)
          .Take(pageSize)
          .ToArrayAsync();

      if (!users.Any())
      {
        return NotFound("Users not Found");
      }
      else
      {
        return Ok(users);
      }
    }

