private void CheckForCycle(bool[] done, int customer)
{
            int start = customer;
            int count = 1;
            while (_nextArray[customer] >= 0)
            {
                done[customer] = true;

                if (_nextArray[customer] == start)
                {
                    _cycles.Add(start, count);
                    break;
                }

                count++;
                customer = _nextArray[customer];

                if (count > _nextArray.Length)
                {
                    break;
                }
            }
        }

