				fixed (UInt64* ptrpSurface = &pSurface.m) {
					result = Linux.Interop.NativeMethods.vkCreateMirSurfaceKHR (instance.m, pCreateInfo != null ? pCreateInfo.m : (Linux.Interop.MirSurfaceCreateInfoKhr*)default(IntPtr), pAllocator != null ? pAllocator.m : null, ptrpSurface);
