private static object processObject(object obj)
{
			if (obj == null)
				return null;
			//Get the type and if it has a copiable value
			Type tp = obj.GetType();
			if (tp.IsValueType || tp == typeof(string))
			{
				return obj;
			}
			else if (tp.IsArray)
			{
				//Process every element of the array
				Type elementType = Type.GetType(tp.FullName.Replace("[]", string.Empty));
				Array array = obj as Array;
				Array copied = Array.CreateInstance(elementType, array.Length);
				for (int i = 0; i < array.Length; i++)
				{
					//Recursive: repeat the process foreach value of the array
					copied.SetValue(processObject(array.GetValue(i)), i);
				}
				//Return the array as the object
				return Convert.ChangeType(copied, obj.GetType());
			}
			else if (tp.IsClass)
			{
				//Process class
				object copy = Activator.CreateInstance(obj.GetType());
				FieldInfo[] fields = tp.GetFields(BindingFlags.Public |
							BindingFlags.NonPublic | BindingFlags.Instance);
				foreach (FieldInfo field in fields)
				{
					object fieldValue = field.GetValue(obj);
					if (fieldValue == null)
						continue;
					//Recursive: foreach field repeat the process to copy the value
					field.SetValue(copy, processObject(fieldValue));
				}
				//Return the completed copy of the object
				return copy;
			}
			//TODO: Handle the other object possibilities
			else
				throw new ArgumentException("Unknown type");
		}

else if (tp.IsArray)
{
				//Process every element of the array
				Type elementType = Type.GetType(tp.FullName.Replace("[]", string.Empty));
				Array array = obj as Array;
				Array copied = Array.CreateInstance(elementType, array.Length);
				for (int i = 0; i < array.Length; i++)
				{
					//Recursive: repeat the process foreach value of the array
					copied.SetValue(processObject(array.GetValue(i)), i);
				}
				//Return the array as the object
				return Convert.ChangeType(copied, obj.GetType());
			}

else if (tp.IsClass)
{
				//Process class
				object copy = Activator.CreateInstance(obj.GetType());
				FieldInfo[] fields = tp.GetFields(BindingFlags.Public |
							BindingFlags.NonPublic | BindingFlags.Instance);
				foreach (FieldInfo field in fields)
				{
					object fieldValue = field.GetValue(obj);
					if (fieldValue == null)
						continue;
					//Recursive: foreach field repeat the process to copy the value
					field.SetValue(copy, processObject(fieldValue));
				}
				//Return the completed copy of the object
				return copy;
			}

public void Execute(IExampleInterface app)
{
            this.app = app;

            // Create the neural network.
            BasicLayer hopfield;
            var network = new HopfieldNetwork(4);

            // This pattern will be trained
            bool[] pattern1 = {true, true, false, false};
            // This pattern will be presented
            bool[] pattern2 = {true, false, false, false};
            IMLData result;

            var data1 = new BiPolarMLData(pattern1);
            var data2 = new BiPolarMLData(pattern2);
            var set = new BasicMLDataSet();
            set.Add(data1);

            // train the neural network with pattern1
            app.WriteLine("Training Hopfield network with: "
                          + FormatBoolean(data1));

            network.AddPattern(data1);
            // present pattern1 and see it recognized
            result = network.Compute(data1);
            app.WriteLine("Presenting pattern:" + FormatBoolean(data1)
                          + ", and got " + FormatBoolean(result));
            // Present pattern2, which is similar to pattern 1. Pattern 1
            // should be recalled.
            result = network.Compute(data2);
            app.WriteLine("Presenting pattern:" + FormatBoolean(data2)
                          + ", and got " + FormatBoolean(result));
        }

public String FormatBoolean(IMLData b)
{
            var result = new StringBuilder();
            result.Append('[');
            for (int i = 0; i < b.Count; i++)
            {
                if (b[i] > 0)
                {
                    result.Append("T");
                }
                else
                {
                    result.Append("F");
                }
                if (i != b.Count - 1)
                {
                    result.Append(",");
                }
            }
            result.Append(']');
            return (result.ToString());
        }

