private IEnumerable<int> MergeArrays(int[] a1, int[] a2)
{
			int i = 0, j = 0;
			while (true)
			{
				if (i == a1.Length && j == a2.Length) yield break;

				if (i == a1.Length)
				{
					yield return a2[j];
					j++;
				}
				else if (j == a2.Length)
				{
					yield return a1[i];
					i++;
				}
				else
				{
					if (a1[i] <= a2[j])
					{
						yield return a1[i];
						i++;
					}
					else
					{
						yield return a2[j];
						j++;
					}
				}
