protected static bool Invoke(string initialSubject, ICommand q, IQueueTools tools, IOutput output, IInput input)
{
            if (string.IsNullOrEmpty(initialSubject))
            {
                return ExecuteSafelyForEachInput(input, tools, output, q.Execute);
            }

            return ExecuteSafely(initialSubject, tools, output, (Func<string, IQueueTools, IOutput, bool>)q.Execute);

        }

protected static bool ExecuteSafely(string subject, IQueueTools tools, IOutput output, Func<string, IQueueTools, IOutput, bool> action)
{
            try
            {
                return action.Invoke(subject, tools, output);
            }
            catch (Exception e)
            {
                output.Error(subject, e.Message);
                return false;
            }
        }

protected static bool ExecuteSafelyForEachInput(IInput input, IQueueTools tools, IOutput output, Func<string, IQueueTools, IOutput, bool> f)
{
            string line = string.Empty;
            bool res = false;

            while(!string.IsNullOrEmpty(line = input.ReadLine()))
            {
                var exres = ExecuteSafely(line, tools, output, f);
                res = res || exres;
            }

            return res ;
        }

public override void VisitIdentifierName(IdentifierNameSyntax node)
{
            CancellationToken.ThrowIfCancellationRequested();

            if (string.Equals(Symbol.Name, node.Identifier.ValueText, StringComparison.Ordinal)
                && !IsInvoked(node)
                && SymbolEqualityComparer.Default.Equals(SemanticModel.GetSymbol(node, CancellationToken), Symbol))
            {
                Result = true;
            }

            static bool IsInvoked(IdentifierNameSyntax identifierName)
            {
                SyntaxNode parent = identifierName.Parent;

                switch (parent.Kind())
                {
                    case SyntaxKind.InvocationExpression:
                        {
                            return true;
                        }
                    case SyntaxKind.SimpleMemberAccessExpression:
                    case SyntaxKind.MemberBindingExpression:
                        {
                            if (parent.IsParentKind(SyntaxKind.InvocationExpression))
                                return true;

                            break;
                        }
                }

                return false;
            }
        }

static bool IsInvoked(IdentifierNameSyntax identifierName)
{
                SyntaxNode parent = identifierName.Parent;

                switch (parent.Kind())
                {
                    case SyntaxKind.InvocationExpression:
                        {
                            return true;
                        }
                    case SyntaxKind.SimpleMemberAccessExpression:
                    case SyntaxKind.MemberBindingExpression:
                        {
                            if (parent.IsParentKind(SyntaxKind.InvocationExpression))
                                return true;

                            break;
                        }
                }

                return false;
            }

public static bool IsReferencedAsMethodGroup(
            MethodDeclarationSyntax methodDeclaration,
            IMethodSymbol methodSymbol,
            SemanticModel semanticModel,
            CancellationToken cancellationToken = default)
{
            var typeDeclaration = (TypeDeclarationSyntax)methodDeclaration.Parent;

            return IsReferencedAsMethodGroup(typeDeclaration, methodSymbol, semanticModel, cancellationToken);
        }

public static bool IsReferencedAsMethodGroup(
            LocalFunctionStatementSyntax localFunction,
            IMethodSymbol methodSymbol,
            SemanticModel semanticModel,
            CancellationToken cancellationToken = default)
{
            MemberDeclarationSyntax memberDeclaration = localFunction.FirstAncestor<MemberDeclarationSyntax>();

            return IsReferencedAsMethodGroup(memberDeclaration, methodSymbol, semanticModel, cancellationToken);
        }

public static bool IsReferencedAsMethodGroup(
            SyntaxNode node,
            IMethodSymbol methodSymbol,
            SemanticModel semanticModel,
            CancellationToken cancellationToken)
{
            var result = false;

            MethodReferencedAsMethodGroupWalker walker = null;

            try
            {
                walker = GetInstance();

                walker.Symbol = methodSymbol;
                walker.SemanticModel = semanticModel;
                walker.CancellationToken = cancellationToken;

                walker.Visit(node);

                result = walker.Result;
            }
            finally
            {
                if (walker != null)
                    Free(walker);
            }

            return result;
        }

private static MethodReferencedAsMethodGroupWalker GetInstance()
{
            MethodReferencedAsMethodGroupWalker walker = _cachedInstance;

            if (walker != null)
            {
                Debug.Assert(walker.Symbol == null);
                Debug.Assert(walker.SemanticModel == null);
                Debug.Assert(walker.CancellationToken == default);

                _cachedInstance = null;
                return walker;
            }

            return new MethodReferencedAsMethodGroupWalker();
        }

private static void Free(MethodReferencedAsMethodGroupWalker walker)
{
            walker.Result = false;
            walker.Symbol = null;
            walker.SemanticModel = null;
            walker.CancellationToken = default;

            _cachedInstance = walker;
        }

