public bool ValidateOld()
{
                // Password must contain no more than the maximum and no less than the minimum of
                // the required character.
                int found = 0;
                foreach (char c in Password)
                {
                    if (c == Required)
                    {
                        found++;
                    }
                    if (found > Max)
                    {
                        return false;
                    }
                }
                return found >= Min;
            }

