public async Task MessageReceivedAsync(SocketMessage rawMsg)
{
            // Ignore system messages, or messages from other bots
            if (!(rawMsg is SocketUserMessage msg)) return;
            if (msg.Source != MessageSource.User) return;
            if (msg.Channel is IDMChannel && Configurations.OwnerId != 0)
            {
                if (msg.Content == $"{Configurations.CommandPrefix}listen")
                {
                    _listen = !_listen;
                    await msg.Author.SendMessageAsync($"Listening: {_listen}");
                    return;
                }

                _output += $"{msg.Author.Username}#{msg.Author.Discriminator}: {msg.Content}\n";

                TimeSpan duration = DateTime.Now.Subtract(_timeToSend);

                if (duration.TotalSeconds > 0 && _output != "")
                {
                    _timeToSend = DateTime.Now.AddSeconds(10);

                    if (_output.Length > 2000)
                        _output = _output.Substring(0, 1999);

                    await _discord
                        .GetUser(Configurations.OwnerId)
                        .GetOrCreateDMChannelAsync()
                        .Result
                        .SendMessageAsync(_output);

                    _output = "";
                }
            }
        }

public object DeserializeFromString(string xml, Type type)
{
            try
            {
                var bytes = Encoding.UTF8.GetBytes(xml);

#if IOS				
                using (var reader = XmlDictionaryReader.CreateTextReader(bytes, null))
#elif SL5 && !WP
                using (var reader = XmlDictionaryReader.CreateTextReader(bytes, XmlDictionaryReaderQuotas.Max))
#elif WP
                using (var reader = XmlDictionaryReader.CreateBinaryReader(bytes, XmlDictionaryReaderQuotas.Max))
#else
                using (var reader = XmlDictionaryReader.CreateTextReader(bytes, this.quotas))
#endif
                {
                    var serializer = new System.Runtime.Serialization.DataContractSerializer(type);
                    return serializer.ReadObject(reader);
                }
            }
            catch (Exception ex)
            {
                throw new SerializationException("DeserializeDataContract: Error converting type: " + ex.Message, ex);
            }
        }

