            if (ctrl.Length >= 1)
            {
                int newRainbowN = Math.Max(1, Math.Min(32, (int)(ctrl[0].Value + 0.5f)));
                if (rainbowN != newRainbowN)
                {
                    rainbowN = newRainbowN;
                    UpdateRainbowN();
                }
            }
            if (ctrl.Length >= 2)
            {
                detuneAmount = ctrl[1].Value;
            }
            if (ctrl.Length >= 3)
