public override int Next()
{
            var retval = (int)(0x7FFFFFFF & NextUInt32());
            if (retval == 0x7FFFFFFF)
                return NextInt32();
            return retval;
        }

public int NextInt32()
{
            return (int)(0x7FFFFFFF & NextUInt32());
        }

public override double NextDouble()
{
            return RealUnitInt * NextInt32();
        }

