                                Tooltip = $"This utxo was exposed through a payjoin proposal for an invoice {idInLabel}",
                                Link = string.IsNullOrEmpty(id)
                                    ? null
                                    : _linkGenerator.InvoiceLink(id, request.Scheme, request.Host, request.PathBase)
                            };
                        case "payout":
